def init_private_attributes(self: BaseModel, context: Any, /) -> None:
    """This function is meant to behave like a BaseModel method to initialise private attributes.

    It takes context as an argument since that's what pydantic-core passes when calling it.

    Args:
        self: The BaseModel instance.
        context: The context.
    """
    # Check if private attributes are already initialized
    existing_private = getattr(self, '__pydantic_private__', None) or {}

    # Create a new dict for private attributes
    pydantic_private = {}

    # Initialize private attributes that don't already exist
    for name, private_attr in self.__private_attributes__.items():
        # If the attribute already exists in __pydantic_private__, keep its current value
        if name in existing_private:
            pydantic_private[name] = existing_private[name]
        else:
            # Otherwise, set it to the default value
            default = private_attr.get_default()
            if default is not PydanticUndefined:
                pydantic_private[name] = default

    object_setattr(self, '__pydantic_private__', pydantic_private)
